const mode = view.mode;
const norm = (s) => std.normalize(String(s ?? "")).normalize("NFD").replace(/[\u0300-\u036f]/g, "");
const lev = (a, b) => {
  const d = Array.from({ length: a.length + 1 }, (_, i) => [i, ...Array(b.length).fill(0)]);
  for (let j = 1; j <= b.length; j++) d[0][j] = j;
  for (let i = 1; i <= a.length; i++) for (let j = 1; j <= b.length; j++)
    d[i][j] = Math.min(d[i - 1][j] + 1, d[i][j - 1] + 1, d[i - 1][j - 1] + (a[i - 1] === b[j - 1] ? 0 : 1));
  return d[a.length][b.length];
};
const nameScore = (given, names) => {
  const g = norm(given);
  if (!g) return { score: 0, feedback: "No answer." };
  if (names.some((n) => norm(n) === g)) return { score: 1 };
  const close = names.find((n) => norm(n).length >= 5 && lev(norm(n), g) === 1);
  if (close) return { score: 0.5, feedback: `Almost: it's spelled ${close}.` };
  return { score: 0, feedback: `It's ${names[0]}.` };
};
const symbolScore = (given, sym) => {
  const g = String(given ?? "").trim();
  if (!g) return { score: 0, feedback: "No answer." };
  if (g === sym) return { score: 1 };
  if (g.toLowerCase() === sym.toLowerCase()) return { score: 0.5, feedback: `Right letters, wrong case: it's written ${sym}. A symbol starts with a capital and any second letter is small.` };
  return { score: 0, feedback: `It's ${sym}.` };
};
// Electron configurations: expand noble-gas cores, then compare orbital by orbital, in any order.
const CORE = { He: "1s2", Ne: "1s2 2s2 2p6", Ar: "1s2 2s2 2p6 3s2 3p6", Kr: "1s2 2s2 2p6 3s2 3p6 3d10 4s2 4p6", Xe: "1s2 2s2 2p6 3s2 3p6 3d10 4s2 4p6 4d10 5s2 5p6", Rn: "1s2 2s2 2p6 3s2 3p6 3d10 4s2 4p6 4d10 5s2 5p6 4f14 5d10 6s2 6p6" };
const SUP = { "⁰": "0", "¹": "1", "²": "2", "³": "3", "⁴": "4", "⁵": "5", "⁶": "6", "⁷": "7", "⁸": "8", "⁹": "9" };
const orbitals = (s) => {
  let t = String(s ?? "").replace(/[⁰¹²³⁴⁵⁶⁷⁸⁹]+/g, (run) => [...run].map((c) => SUP[c]).join("") + " ").replace(/\^/g, "");
  t = t.replace(/\[\s*([A-Za-z]{2})\s*\]/g, (m, g) => { const k = g[0].toUpperCase() + g[1].toLowerCase(); return CORE[k] ? " " + CORE[k] + " " : " ?? "; });
  const map = {};
  let bad = /\?\?/.test(t);
  const rest = t.replace(/([1-7])\s*([spdf])\s*(\d{1,2})/gi, (m, n, l, c) => { const k = n + l.toLowerCase(); map[k] = (map[k] ?? 0) + Number(c); return " "; });
  if (/[A-Za-z0-9]/.test(rest)) bad = true;
  return { map, bad };
};
const same = (a, b) => { const ks = new Set([...Object.keys(a), ...Object.keys(b)]); return [...ks].every((k) => (a[k] ?? 0) === (b[k] ?? 0)); };

if (mode === "symbol") return symbolScore(answer, key.symbol);
if (mode === "name") return nameScore(answer, key.names);
if (mode === "identify") {
  const g = String(answer ?? "").trim();
  if (g === key.symbol) return { score: 1 };
  if (norm(g).length > 2 || key.names.some((n) => norm(n) === norm(g))) return nameScore(g, key.names);
  return symbolScore(g, key.symbol);
}
if (mode === "locate") {
  const pick = Number(answer?.z ?? answer);
  if (!pick) return { score: 0, feedback: "No cell picked.", details: { pick: null } };
  if (pick === key.z) return { score: 1, details: { pick } };
  return { score: 0, details: { pick } };
}
if (mode === "numbers") {
  const a = answer ?? {};
  const parts = view.parts.map((p) => ({ p, ok: Number(std.parseNumber(String(a[p] ?? ""))) === Number(key[p]) }));
  const right = parts.filter((x) => x.ok).length;
  const wrong = parts.filter((x) => !x.ok).map((x) => ({ z: "atomic number", period: "period", group: "group" })[x.p]);
  return { score: right / parts.length, feedback: wrong.length ? `Check the ${wrong.join(" and ")}.` : undefined, details: { parts } };
}
if (mode === "mass") {
  const x = std.parseNumber(String(answer ?? "").replace(/[\[\]\su]/g, ""));
  if (!Number.isFinite(x)) return { score: 0, feedback: "No number." };
  const off = Math.abs(x - key.mass);
  return { score: off <= key.tol ? 1 : 0, feedback: off <= key.tol ? undefined : `Off by ${std.round(off, 3)}.`, details: { off } };
}
if (mode === "family") {
  const a = answer ?? {};
  const fam = a.family === key.family;
  const blk = key.blocks.includes(a.block);
  return { score: (fam ? 0.5 : 0) + (blk ? 0.5 : 0), feedback: fam && blk ? undefined : [fam ? "" : `It's a ${key.family.toLowerCase()}.`, blk ? "" : `It's in the ${key.blocks.join(" or ")} block.`].filter(Boolean).join(" "), details: { fam, blk } };
}
if (mode === "config") {
  const g = orbitals(answer), k = orbitals(key.config);
  if (!String(answer ?? "").trim()) return { score: 0, feedback: "No answer." };
  if (g.bad) return { score: 0, feedback: "Couldn't read that. Write orbitals like 1s2 2s2 2p6, or a core like [Ne] 3s1." };
  const accepted = (key.configs ?? [key.config]).map(orbitals);
  if (accepted.some((a) => same(g.map, a.map))) return { score: 1 };
  const total = (m) => Object.values(m).reduce((s, v) => s + v, 0);
  const diff = [...new Set([...Object.keys(g.map), ...Object.keys(k.map)])].filter((o) => (g.map[o] ?? 0) !== (k.map[o] ?? 0));
  const fb = total(g.map) !== total(k.map) ? `That's ${total(g.map)} electrons; it needs ${total(k.map)}.` : `Right count, wrong filling: look at ${diff.join(", ")}.`;
  return { score: 0, feedback: fb, details: { diff } };
}
return { score: null };

type.prepare:
const mode = fields.mode || "symbol";
const z = Number(fields.z);
const names = [fields.name, ...(fields.alt ?? [])];
const tile = { z, symbol: fields.symbol, name: fields.name, massText: fields.massText ?? "", family: fields.family ?? "", config: fields.config ?? "", period: fields.period, group: fields.group ?? null, blocks: fields.blocks ?? [], predicted: fields.predicted === true };
const FAMILIES = ["Alkali metal", "Alkaline earth metal", "Transition metal", "Post-transition metal", "Metalloid", "Nonmetal", "Halogen", "Noble gas", "Lanthanide", "Actinide"];
const view = { mode, ask: fields.name };
const key = { tile, note: fields.note ?? "" };
if (mode === "symbol") { key.symbol = fields.symbol; }
else if (mode === "name") { view.ask = fields.symbol; key.names = names; }
else if (mode === "locate") { key.z = z; }
else if (mode === "identify") { view.ask = ""; view.z = z; key.symbol = fields.symbol; key.names = names; }
else if (mode === "numbers") {
  view.parts = ["z", "period"];
  if (fields.group != null && fields.group !== "") view.parts.push("group");
  key.z = z; key.period = fields.period; key.group = fields.group ?? null;
}
else if (mode === "mass") { key.mass = Number(fields.mass); key.tol = Number(fields.massTolerance ?? 0.5); key.massText = fields.massText; }
else if (mode === "family") { view.families = FAMILIES; key.family = fields.family; key.blocks = fields.blocks ?? []; }
else if (mode === "config") { key.config = fields.config; key.configs = [fields.config, ...(fields.configAlt ?? [])]; }
return { view, key };

