// An example answer for watch mode.
const t = key.tile;
switch (view.mode) {
  case "symbol": return t.symbol;
  case "name": return t.name;
  case "identify": return t.symbol;
  case "locate": return { z: t.z };
  case "numbers": return { z: String(t.z), period: String(t.period), group: t.group == null ? "" : String(t.group) };
  case "mass": return String(key.mass);
  case "family": return { family: t.family, block: t.blocks[0] };
  case "config": return t.config;
}
return null;

