.pt-table.live .pt-cell:focus-visible { outline: 2px solid var(--ring); outline-offset: 1px; z-index: 1; }
.pt-table .pt-cell[aria-pressed="true"] { background: color-mix(in oklab, var(--highlight) 60%, transparent); border-color: var(--highlight); transform: scale(1.12); z-index: 1; }
