/* The element's tile, like one cut out of a wall chart. */
.pt-card { display: flex; gap: 1.1rem; align-items: center; flex-wrap: wrap; }
.pt-tile {
  position: relative; width: 7.5rem; height: 7.5rem; flex: none; border-radius: calc(var(--radius) + 2px);
  border: 1.5px solid color-mix(in oklab, var(--c) 70%, transparent);
