.pt-legend i { width: 0.75rem; height: 0.75rem; border-radius: 2px; background: color-mix(in oklab, var(--c) 42%, transparent); border: 1px solid color-mix(in oklab, var(--c) 70%, transparent); }
.pt-nudge { display: flex; align-items: center; gap: 0.4rem; margin-top: 0.7rem; flex-wrap: wrap; }
