.pt-nudge .arrows { display: flex; gap: 0.4rem; }
.pt-nudge .where b { color: var(--foreground); }
.pt-nudge button { width: 42px; height: 42px; display: inline-flex; align-items: center; justify-content: center; border-radius: calc(var(--radius) - 2px); border: 1px solid var(--border); background: transparent; color: var(--foreground); font-size: 1.1rem; cursor: pointer; touch-action: manipulation; }
.pt-nudge button:active { background: var(--accent); }
.pt-nudge[hidden] { display: none; }

template.js:
const { view } = etude;
const mode = view.mode;
const EYE = { symbol: "Symbol", name: "Name", locate: "Find it", identify: "Name the cell", numbers: "Numbers", mass: "Atomic mass", family: "Family and block", config: "Electron configuration" };
const eye = document.querySelector(".sc-eyebrow");
if (eye) eye.textContent = `Periodic table · ${EYE[mode] ?? ""}`;

// Where element z sits: [column 1-18, row]. Rows 1-7 are the main table, 9-10 the f-block underneath.
const posOf = (z) => {
  if (z === 1) return [1, 1];
  if (z === 2) return [18, 1];
  if (z <= 4) return [z - 2, 2];
  if (z <= 10) return [z + 8, 2];
  if (z <= 12) return [z - 10, 3];
  if (z <= 18) return [z, 3];
  if (z <= 36) return [z - 18, 4];
  if (z <= 54) return [z - 36, 5];
  if (z <= 56) return [z - 54, 6];
  if (z <= 71) return [z - 54, 9];
  if (z <= 86) return [z - 68, 6];
  if (z <= 88) return [z - 86, 7];
  if (z <= 103) return [z - 86, 10];
  return [z - 100, 7];
};
const ALL = Array.from({ length: 118 }, (_, i) => i + 1);
const SYM = "H He Li Be B C N O F Ne Na Mg Al Si P S Cl Ar K Ca Sc Ti V Cr Mn Fe Co Ni Cu Zn Ga Ge As Se Br Kr Rb Sr Y Zr Nb Mo Tc Ru Rh Pd Ag Cd In Sn Sb Te I Xe Cs Ba La Ce Pr Nd Pm Sm Eu Gd Tb Dy Ho Er Tm Yb Lu Hf Ta W Re Os Ir Pt Au Hg Tl Pb Bi Po At Rn Fr Ra Ac Th Pa U Np Pu Am Cm Bk Cf Es Fm Md No Lr Rf Db Sg Bh Hs Mt Ds Rg Cn Nh Fl Mc Lv Ts Og".split(" ");
// Families for colouring the table after an answer (same classes as the tile).
const FAM = (z) => {
  if (z >= 57 && z <= 71) return "lan";
  if (z >= 89 && z <= 103) return "act";
  if ([3, 11, 19, 37, 55, 87].includes(z)) return "alk";
  if ([4, 12, 20, 38, 56, 88].includes(z)) return "ae";
  if ([2, 10, 18, 36, 54, 86, 118].includes(z)) return "nob";
  if ([9, 17, 35, 53, 85, 117].includes(z)) return "hal";
  if ([1, 6, 7, 8, 15, 16, 34].includes(z)) return "non";
  if ([5, 14, 32, 33, 51, 52, 84].includes(z)) return "met";
  if ([13, 31, 49, 50, 81, 82, 83, 113, 114, 115, 116].includes(z)) return "post";
  return "tm";
};
const famClass = { "Alkali metal": "alk", "Alkaline earth metal": "ae", "Transition metal": "tm", "Post-transition metal": "post", "Metalloid": "met", "Nonmetal": "non", "Halogen": "hal", "Noble gas": "nob", "Lanthanide": "lan", "Actinide": "act" };

const SUP = "⁰¹²³⁴⁵⁶⁷⁸⁹";
const pretty = (s) => etude.escape(String(s ?? "")).replace(/([spdf])\s*\^?(\d{1,2})/g, (m, l, n) => l + [...n].map((d) => SUP[d]).join(""));
const countE = (s) => {
  const CORE = { He: 2, Ne: 10, Ar: 18, Kr: 36, Xe: 54, Rn: 86 };
  let n = 0;
  String(s).replace(/\[\s*([A-Za-z]{2})\s*\]/g, (m, g) => { n += CORE[g[0].toUpperCase() + g[1].toLowerCase()] ?? 0; return ""; })
    .replace(/[1-7]\s*[spdf]\s*\^?(\d{1,2})/gi, (m, c) => { n += Number(c); return ""; });
  return n;
};

// The table. labels: show group and period numbers. cells get data-z.
const table = ({ interactive = false, filled = false, mark = null, mine = null, colored = false } = {}) => {
  const cells = [];
  for (let g = 1; g <= 18; g++) cells.push(`<span class="pt-lab top" style="grid-column:${g + 1};grid-row:1">${g}</span>`);
  for (let p = 1; p <= 7; p++) cells.push(`<span class="pt-lab side" style="grid-column:1;grid-row:${p + 1}">${p}</span>`);
  cells.push(`<span class="pt-cell ref" style="grid-column:4;grid-row:7">*</span><span class="pt-cell ref" style="grid-column:4;grid-row:8">**</span>`);
  cells.push(`<span class="pt-lab side f" style="grid-column:2 / span 2;grid-row:10">*</span><span class="pt-lab side f" style="grid-column:2 / span 2;grid-row:11">**</span>`);
  for (const z of ALL) {
    const [c, r] = posOf(z);
    const cls = ["pt-cell", colored ? "f-" + FAM(z) : "", z === mark ? "mark" : "", z === mine && mine !== mark ? "mine" : ""].filter(Boolean).join(" ");
    const txt = filled ? `<span class="s">${SYM[z - 1]}</span>` : "";
    const tag = interactive ? "button" : "span";
    const attrs = interactive ? ` type="button" tabindex="${z === 1 ? 0 : -1}"${z === 1 ? ' data-first="1"' : ""} aria-label="${r === 9 ? `Lanthanide row, cell ${c - 2}` : r === 10 ? `Actinide row, cell ${c - 2}` : `Period ${r}, group ${c}`}"` : "";
    cells.push(`<${tag} class="${cls}" data-z="${z}"${attrs} style="grid-column:${c + 1};grid-row:${r + 1}">${txt}</${tag}>`);
  }
  const legend = colored ? `<div class="pt-legend">${Object.entries(famClass).map(([n, c]) => `<span class="f-${c}"><i></i>${n}</span>`).join("")}</div>` : "";
  return `<div class="pt-wrap"><div class="pt-table${interactive ? " live" : ""}">${cells.join("")}</div>${legend}</div>`;
};

const q = etude.$(".pt-q");
const work = etude.$(".pt-work");
const help = etude.$(".pt-help");
const ask = (big, line, cls = "") => (q.innerHTML = `${big ? `<div class="pt-big ${cls}">${etude.escape(big)}</div>` : ""}<div class="pt-line">${line}</div>`);
const input = (ph, opts = "") => `<input class="e-input pt-in" autocomplete="off" autocapitalize="off" spellcheck="false" placeholder="${ph}" ${opts} autofocus>`;
const enterSubmits = (el) => el.addEventListener("keydown", (e) => { if (e.key === "Enter" && !e.ctrlKey && !e.metaKey) { e.preventDefault(); if (el.value.trim()) etude.submit(); } });

let picked = null;
const prev = etude.answer;

if (mode === "symbol" || mode === "name" || mode === "mass" || mode === "config") {
  if (mode === "symbol") { ask(view.ask, "What's its symbol?"); work.innerHTML = input("Symbol", 'maxlength="3"') ; }
  if (mode === "name") { ask(view.ask, "Which element is this?", "sym"); work.innerHTML = input("Element name"); }
  if (mode === "mass") { ask(view.ask, "What's its atomic mass?"); work.innerHTML = `<div class="e-row pt-row">${input("Atomic mass", 'inputmode="decimal"')}<span class="e-unit">u</span></div>`; help.innerHTML = "Close is enough: within half a unit. For an element with no stable isotope, the mass number of its longest-lived one, as printed in [brackets]."; }
  if (mode === "config") {
    ask(view.ask, `Write its electron configuration.`);
    work.innerHTML = `${input("[Ne] 3s2 3p4", 'class="mono"')}<div class="pt-preview" aria-live="polite"></div>`;
    help.innerHTML = "Type orbitals like <code>1s2 2s2 2p6</code>, with a noble-gas core if you like: <code>[Ne] 3s1</code>. Any order.";
    const pv = etude.$(".pt-preview");
    const el = etude.$(".pt-in");
    el.classList.add("mono");
    const show = () => { const v = el.value.trim(); pv.innerHTML = v ? `<span class="cfg">${pretty(v)}</span><span class="e-muted">${countE(v)} electrons</span>` : ""; };
    el.addEventListener("input", show);
    if (typeof prev === "string") { el.value = prev; show(); }
  }
  const el = etude.$(".pt-in");
  if (typeof prev === "string" && mode !== "config") el.value = prev;
  etude.setReady(!!el.value.trim());
  el.addEventListener("input", () => etude.setReady(!!el.value.trim()));
  enterSubmits(el);
  etude.getAnswer(() => el.value.trim());
  etude.onResult(({ grade }) => { el.disabled = true; el.classList.add(grade.score >= 1 ? "is-correct" : "is-wrong"); });
}

if (mode === "identify") {
  ask("", "Which element sits in the marked cell? Its symbol or its name.");
  work.innerHTML = table({ mark: view.z }) + `<div class="pt-under">${input("Symbol or name")}</div>`;
  const el = etude.$(".pt-in");
  if (typeof prev === "string") el.value = prev;
  etude.setReady(!!el.value.trim());
  el.addEventListener("input", () => etude.setReady(!!el.value.trim()));
  enterSubmits(el);
  etude.getAnswer(() => el.value.trim());
  etude.onResult(({ grade }) => { el.disabled = true; el.classList.add(grade.score >= 1 ? "is-correct" : "is-wrong"); });
}

if (mode === "locate") {
  ask(view.ask, "Tap its place on the table.");
  help.innerHTML = "Tap a cell, then Check. Keyboard: arrows to move, <kbd>Space</kbd> to pick.";
  // Park the initial focus on the question so no cell starts with a ring that looks like a pick; Tab still reaches the table.
  q.tabIndex = -1; q.setAttribute("autofocus", ""); q.style.outline = "none";
  work.innerHTML = table({ interactive: true }) + `<div class="pt-nudge only-answer" hidden><span class="where"></span><span class="arrows">${[["←", "ArrowLeft"], ["↑", "ArrowUp"], ["↓", "ArrowDown"], ["→", "ArrowRight"]].map(([a, k]) => `<button type="button" data-k="${k}" aria-label="Move ${k.slice(5).toLowerCase()}">${a}</button>`).join("")}</span></div>`;
  const cells = etude.$$(".pt-table .pt-cell[data-z]");
  const byZ = Object.fromEntries(cells.map((c) => [c.dataset.z, c]));
  const nudge = etude.$(".pt-nudge");
  // Where a cell is, in words, without naming it: on a phone the cells are small, so this and the arrows fix a near miss.
  const where = (z) => {
    const [c, r] = posOf(z);
    if (r >= 9) return `<b>${r === 9 ? "Lanthanide" : "Actinide"} row</b>, cell <b>${c - 2}</b> of 15`;
    return `Period <b>${r}</b>, group <b>${c}</b>`;
  };
  const choose = (z) => {
    if (etude.mode !== "answer") return;
    picked = z;
    cells.forEach((c) => c.setAttribute("aria-pressed", String(Number(c.dataset.z) === z)));
    nudge.hidden = false;
    nudge.querySelector(".where").innerHTML = where(z);
    etude.setReady(true);
  };
  work.addEventListener("click", (e) => { const c = e.target.closest(".pt-cell[data-z]"); if (c && c.tagName === "BUTTON") choose(Number(c.dataset.z)); });
  // Arrow keys move to the nearest cell in that direction.
  const step = (z, key) => {
    const [x, y] = posOf(z);
    const d = { ArrowRight: [1, 0], ArrowLeft: [-1, 0], ArrowDown: [0, 1], ArrowUp: [0, -1] }[key];
    let best = null, bd = 1e9;
    for (const w of ALL) {
      const [a, b] = posOf(w);
      const dx = a - x, dy = b - y;
      if ((d[0] && Math.sign(dx) !== d[0]) || (d[1] && Math.sign(dy) !== d[1])) continue;
      const along = d[0] ? Math.abs(dx) : Math.abs(dy), across = d[0] ? Math.abs(dy) : Math.abs(dx);
      const sc = along + across * 3;
      if (sc < bd) { bd = sc; best = w; }
    }
    return best;
  };
  nudge.addEventListener("click", (e) => {
    const b = e.target.closest("button[data-k]");
    if (!b || !picked) return;
    const n = step(picked, b.dataset.k);
    if (n) choose(n);
  });
  work.addEventListener("keydown", (e) => {
    const c = e.target.closest(".pt-cell[data-z]");
    if (!c || e.ctrlKey || e.metaKey || e.altKey) return;
    if (e.key.startsWith("Arrow")) {
      e.preventDefault();
      const best = step(Number(c.dataset.z), e.key);
      if (best) { c.tabIndex = -1; byZ[best].tabIndex = 0; byZ[best].focus(); }
    } else if (e.key === " " || e.key === "Enter") { e.preventDefault(); choose(Number(c.dataset.z)); }
  });
  if (prev && prev.z) choose(Number(prev.z)); else etude.setReady(false);
  etude.getAnswer(() => {
    if (!picked) return null;
    return { z: picked };
  });
}

if (mode === "numbers") {
  ask(view.ask, "Give its numbers.");
  const lab = { z: "Atomic number", period: "Period", group: "Group" };
  work.innerHTML = `<div class="pt-nums">${view.parts.map((p, i) => `<label class="pt-num"><span class="e-label">${lab[p]}</span><input class="e-input" data-p="${p}" inputmode="numeric" autocomplete="off" ${i === 0 ? "autofocus" : ""}></label>`).join("")}</div>`;
  if (!view.parts.includes("group")) help.innerHTML = "Lanthanides and actinides sit outside the 18 groups, so there's no group to give.";
  const ins = etude.$$(".pt-nums input");
  if (prev) ins.forEach((i) => (i.value = prev[i.dataset.p] ?? ""));
  const ready = () => etude.setReady(ins.every((i) => i.value.trim()));
  ins.forEach((i, k) => {
    i.addEventListener("input", ready);
    i.addEventListener("keydown", (e) => { if (e.key === "Enter" && !e.ctrlKey && !e.metaKey) { e.preventDefault(); if (ins[k + 1]) ins[k + 1].focus(); else if (ins.every((x) => x.value.trim())) etude.submit(); } });
  });
  ready();
  etude.getAnswer(() => Object.fromEntries(ins.map((i) => [i.dataset.p, i.value.trim()])));
  etude.onResult(({ grade }) => {
    const parts = grade.details?.parts ?? [];
    ins.forEach((i) => { i.disabled = true; const r = parts.find((x) => x.p === i.dataset.p); if (r) i.classList.add(r.ok ? "is-correct" : "is-wrong"); });
  });
}

if (mode === "family") {
  ask(view.ask, "Which family is it in, and which block?");
  work.innerHTML = `<div class="e-label">Family</div><div class="pt-fams">${view.families.map((f) => `<button type="button" class="e-option pt-fam f-${famClass[f]}" data-v="${f}"><span class="sw"></span>${f}</button>`).join("")}</div>
    <div class="e-label">Block</div><div class="pt-blocks">${["s", "p", "d", "f"].map((b) => `<button type="button" class="e-option pt-blk" data-v="${b}">${b}</button>`).join("")}</div>`;
  let fam = prev?.family ?? null, blk = prev?.block ?? null;
  const paint = () => {
    etude.$$(".pt-fam").forEach((b) => b.setAttribute("aria-pressed", String(b.dataset.v === fam)));
    etude.$$(".pt-blk").forEach((b) => b.setAttribute("aria-pressed", String(b.dataset.v === blk)));
    etude.setReady(!!fam && !!blk);
  };
  work.addEventListener("click", (e) => {
    if (etude.mode !== "answer") return;
    const b = e.target.closest(".e-option");
    if (!b) return;
    if (b.classList.contains("pt-fam")) fam = b.dataset.v; else blk = b.dataset.v;
    paint();
  });
  window.addEventListener("keydown", (e) => { if (etude.mode === "answer" && /^[spdf]$/.test(e.key) && e.target.tagName !== "INPUT") { blk = e.key; paint(); } });
  paint();
  etude.getAnswer(() => ({ family: fam, block: blk }));
  etude.onResult(({ key }) => {
    etude.$$(".pt-fam").forEach((b) => { b.disabled = true; if (b.dataset.v === key.family) b.classList.add("is-correct"); else if (b.dataset.v === fam) b.classList.add("is-wrong"); });
    etude.$$(".pt-blk").forEach((b) => { b.disabled = true; if (key.blocks.includes(b.dataset.v)) b.classList.add("is-correct"); else if (b.dataset.v === blk) b.classList.add("is-wrong"); });
  });
}

// After grading: the element's tile, its facts, and its place on the table.
etude.onResult(({ key, answer, grade }) => {
  const t = key.tile;
  const fc = famClass[t.family] ?? "";
  const pr = t.period, gr = t.group;
  const facts = [
    `<span>Atomic number <b>${t.z}</b></span>`,
    `<span>Period <b>${pr}</b></span>`,
    gr ? `<span>Group <b>${gr}</b></span>` : `<span>No group (${t.family === "Actinide" ? "actinide" : "lanthanide"} row)</span>`,
    `<span><b>${t.blocks.join(" / ")}</b>-block</span>`,
  ].join("");
  const tileHtml = `<div class="pt-tile f-${fc}"><span class="tz">${t.z}</span><span class="tm">${etude.escape(t.massText)}</span><span class="ts">${etude.escape(t.symbol)}</span><span class="tn">${etude.escape(t.name)}</span></div>`;
  const side = `<div class="pt-facts"><div class="fam"><span class="sw f-${fc}"></span>${etude.escape(t.family)}${t.predicted ? ' <span class="e-muted">(predicted)</span>' : ""}</div><div class="nums">${facts}</div><div class="cfg">${pretty(t.config)}${t.predicted ? ' <span class="e-muted">predicted</span>' : ""}</div></div>`;
  const out = etude.$(".pt-result");
  if (!out) return;
  if (mode === "locate") {
    const pick = Number(answer?.z ?? 0) || null;
    work.innerHTML = table({ filled: true, colored: true, mark: t.z, mine: pick });
    out.innerHTML = `<div class="pt-card">${tileHtml}${side}</div>`;
    if (pick && pick !== t.z) out.insertAdjacentHTML("beforeend", `<p class="e-muted pt-yours">You picked <b>${SYM[pick - 1]}</b>, period ${posOf(pick)[1] > 8 ? posOf(pick)[1] - 3 : posOf(pick)[1]}.</p>`);
  } else if (mode === "identify") {
    work.querySelector(".pt-wrap").outerHTML = table({ filled: true, colored: true, mark: t.z });
    out.innerHTML = `<div class="pt-card">${tileHtml}${side}</div>`;
  } else {
    out.innerHTML = `<div class="pt-card">${tileHtml}${side}</div>${table({ filled: true, colored: true, mark: t.z })}`;
  }
});
